"""Bound the 5299 word lookup from literal instruction widths and byte operations."""
import argparse, hashlib, json, struct
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1]
def main():
 p=argparse.ArgumentParser(description=__doc__);p.add_argument('--output',type=Path,required=True);a=p.parse_args();out=a.output.resolve();assert not out.exists() and out.is_relative_to(ROOT/'docs/recovery/evidence')
 image=(ROOT/'analysis/derived/td2ega-v1/TD2EGA.image.bin').read_bytes();sha=hashlib.sha256(image).hexdigest();assert sha=='8db38a02cc318a62b15928e217bb9f935699c6566088c21d32382a1c908a59c4'
 expected={0x52bd:'33d2',0x52c4:'247f',0x52c6:'98',0x52c7:'d1e0',0x52c9:'d1e0',0x52cd:'8a847f34',0x52d5:'3ad0',0x52d7:'7702',0x52d9:'8ad0',0x52dd:'0ad2',0x52df:'7d02',0x52e1:'f6da',0x52e3:'8bda',0x52e5:'d1e3',0x52e7:'8b87ee32'}
 for ip,raw in expected.items():assert image[0x6c90+ip:0x6c90+ip+len(raw)//2].hex()==raw
 indices=sorted({((-v)&255) if v&128 else v for v in range(256)});assert indices==list(range(129));start=0x178f0+0x32ee;length=2*(max(indices)+1);assert length==258 and 0x32ee+length-1==0x33ef and 0x33ef<0x3446
 span={'segment':0x178f,'segment_offset':0x32ee,'offset':start,'length':length,'sha256':hashlib.sha256(image[start:start+length]).hexdigest(),'role':'Raw mutable DS32EE word view; byte-absolute DL index0..128,129 words/258 bytes32EE..33EF. Overlaps globals330C/330E/331x/333E/3340, excludes initialized jump tables3446..3469. Values/units/allwriters/actualDS unassigned.'}
 record={'schema':1,'result':'pass','image_sha256':sha,'script_sha256':hashlib.sha256(Path(__file__).read_bytes()).hexdigest(),'instruction_observations':[{'site':f'06C9:{ip:04X}','bytes':raw} for ip,raw in expected.items()],'external_span_candidates':[span],'byte_bound_proof':{'input_byte_values':256,'final_DL_indices':indices,'DH':0,'word_index_max':128,'word_count':129,'word_view_bytes':258,'last_byte':'33EF','strided_sample_offsets':[0x347f+4*i for i in range(128)]},'facts':['XORDXDX before four samples; onlyDL is subsequently updated. Unsigned maximum followed by conditional byteNEG maps everypossibleDL to0..128; DX hasDH0. MOVBXDX/SHLBX1 therefore selects evenwordoffset0..256.','Actual258byte32EEwordview overlaps mutable globals but doesnot reach initialized3446..3469 jumptables. Separate347F stridedbyte lookup uses sampleAND7F andfourfoldindex.','Erratum: frozen tools/validate_record_dispatch.py v2 comment claiming the32EEwordview overlapsallthreejumptables isfalse. Its256word synthetic initialRAM fill exceeded the129word instruction-bounded view and overwrote initialized jumpwords. Restoring finaljumpbytes was fixture setup, notsourcealias evidence. Executed validator/C/DLL/comparison receipts remain frozen; comparison results unchanged.'],'limits':'Static literal5299 bound and initialized span identity only; no resource format/units/allwriters/actualDS/caller/core/device/session/gameplay/fidelity closure.'}
 out.write_text(json.dumps(record,indent=2)+'\n');print(json.dumps({'result':'pass','word_count':129,'word_view_bytes':258,'last_byte':'33EF','jump_table_overlap':False}))
if __name__=='__main__':main()
